-- TEF Reading Test 01: 40 original items, 60 minutes, source-private keys, no AI or wallet changes. Isolated secure TEF Reading schema.
begin;
create schema academy_tef_reading;
revoke all on schema academy_tef_reading from public,anon,authenticated,service_role;
create table academy_tef_reading.papers (
 id text not null, version text not null, content jsonb not null,
 primary key(id,version),
 check(jsonb_typeof(content->'questions')='array' and jsonb_array_length(content->'questions')=40)
);
create table academy_tef_reading.attempts (
 id uuid primary key, user_id uuid not null references auth.users(id),
 test_id text not null, version text not null,
 status text not null default 'active' check(status in ('active','completed')),
 answers jsonb not null default '{}' check(jsonb_typeof(answers)='object'),
 revision integer not null default 0,
 started_at timestamptz not null default now(),
 deadline timestamptz not null default now()+interval '60 minutes',
 submitted_at timestamptz, result jsonb,
 foreign key(test_id,version) references academy_tef_reading.papers(id,version),
 check((status='active' and submitted_at is null and result is null) or (status='completed' and submitted_at is not null and result is not null))
);
create unique index reading_one_active on academy_tef_reading.attempts(user_id) where status='active';
create index reading_owned_history on academy_tef_reading.attempts(user_id,started_at desc);
alter table academy_tef_reading.papers enable row level security;
alter table academy_tef_reading.attempts enable row level security;
revoke all on all tables in schema academy_tef_reading from public,anon,authenticated,service_role;

insert into academy_tef_reading.papers(id,version,content) values('tef-reading-01','tef-reading-2026-11-original-01-v1',$paper${"id":"tef-reading-01","version":"tef-reading-2026-11-original-01-v1","title":"TEF Canada · Compréhension écrite · Test 01","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"🏛️ MÉDIATHÈQUE DES RIVES\nLa salle de lecture fermera jeudi de 9 h à 12 h pour l'installation de nouveaux postes informatiques. Le prêt et le retour des livres restent possibles au comptoir du rez-de-chaussée.","question":"Que pourront faire les usagers jeudi matin ?","options":["Consulter les ouvrages dans la salle habituelle","Assister à une présentation du matériel","Utiliser les nouveaux ordinateurs dès 9 h","Emprunter et rendre des documents au comptoir"],"correct":"D","explanation":"Seule la salle de lecture est fermée : le comptoir reste disponible pour les prêts et retours.","media":{"kind":"notice","icon":"📚","heading":"Information aux lecteurs","accent":"#28609b"}},{"number":2,"points":1,"passage":"🚉 INFORMATION VOYAGEURS\nEn raison de travaux sur la ligne C, les trains ne desserviront pas la station Université dimanche entre 7 h et 13 h. Une navette gratuite reliera les stations Parc et Université toutes les quinze minutes.","question":"Quelle solution est proposée pendant les travaux ?","options":["Un remboursement automatique des abonnements","Une correspondance par la ligne de métro A","Un transport de remplacement sans supplément","L'accès à la station par une autre entrée"],"correct":"C","explanation":"Une navette gratuite assurera la liaison vers la station Université pendant la suspension des trains.","media":{"kind":"notice","icon":"🚉","heading":"Ligne C · Service adapté","accent":"#0e7490"}},{"number":3,"points":1,"passage":"🌿 ATELIER DU JARDIN PARTAGÉ\nSamedi 21 mai, de 10 h à 12 h, apprenez à préparer des semis avec les bénévoles du quartier. Matériel fourni ; participation gratuite sur inscription avant jeudi. Rendez-vous devant la serre municipale.","question":"Que faut-il faire pour participer ?","options":["Apporter ses propres outils de jardinage","Payer les frais de matériel sur place","S'inscrire au plus tard jeudi","Venir à la serre dès vendredi matin"],"correct":"C","explanation":"L'atelier est gratuit et le matériel fourni, mais l'inscription doit être faite avant jeudi.","media":{"kind":"illustration","scene":"garden","heading":"Atelier de jardinage"}},{"number":4,"points":1,"passage":"🎭 FORUM DES ASSOCIATIONS\nDécouvrez les activités du quartier le samedi 10 septembre, de 14 h à 18 h, à la Maison des fêtes. Rencontrez les bénévoles, assistez à des démonstrations et renseignez-vous sur les inscriptions pour l'année.","question":"Quel est l'objectif principal de ce forum ?","options":["Permettre de découvrir les associations locales","Recruter uniquement des animateurs salariés","Présenter le programme d'une troupe de théâtre","Distribuer les billets d'un spectacle municipal"],"correct":"A","explanation":"Le forum met les visiteurs en contact avec plusieurs associations et leurs activités.","media":{"kind":"illustration","scene":"fair","heading":"Forum des associations"}},{"number":5,"points":1,"passage":"🎨 APPEL À CONTRIBUTIONS\nAidez de jeunes illustrateurs à présenter leurs œuvres dans les écoles du département. Chaque don finance l'impression et l'accrochage d'une planche. L'exposition est gratuite pour les établissements ; un reçu est envoyé aux donateurs.","question":"Ce message invite principalement le public à : ","options":["Réserver une œuvre à acheter","Soutenir financièrement une exposition","Demander un stage de dessin","S'inscrire à des cours d'illustration"],"correct":"B","explanation":"L'appel à contributions sert à payer l'impression et l'installation des œuvres.","media":{"kind":"notice","icon":"🎨","heading":"Soutenez les jeunes créateurs","accent":"#8b5cf6"}},{"number":6,"points":1,"passage":"🚲 NOUVEAU SERVICE MUNICIPAL\nQuatre stations de vélos en libre-service viennent d'ouvrir près de la gare. Les abonnés peuvent retirer un vélo dans une station et le rendre dans une autre, sans passer par le guichet.","question":"Quel avantage ce service propose-t-il ?","options":["Faire entretenir gratuitement son vélo personnel","Transporter son vélo à bord de tous les trains","Rendre un vélo dans une station différente","Réserver une place pour un cycliste sur le quai"],"correct":"C","explanation":"Les abonnés peuvent emprunter un vélo dans une station et le déposer dans une autre.","media":{"kind":"notice","icon":"🚲","heading":"Vélos en libre-service","accent":"#16a34a"}},{"number":7,"points":1,"passage":"🧪 SEMAINE DES SCIENCES\nDes collégiens ont présenté des expériences sur la qualité de l'eau et la consommation d'énergie. Les familles ont visité les ateliers et discuté avec les élèves des résultats observés.","question":"Ce texte présente : ","options":["Une compétition sportive entre collèges","Une opération commerciale de matériel scientifique","Une formation réservée aux enseignants","Une activité scolaire de sensibilisation scientifique"],"correct":"D","explanation":"Les élèves présentent leurs expériences et expliquent leurs résultats aux familles.","media":{"kind":"notice","icon":"🧪","heading":"La science à l'école","accent":"#d97706"}},{"number":8,"points":1,"passage":"Pour consulter vos résultats, saisissez votre ________ personnel sur la plateforme.","question":"Quel mot complète la phrase ?","options":["identifiant","parapluie","couloir","emballage"],"correct":"A","explanation":"« Identifiant personnel » désigne les informations de connexion à la plateforme.","section":"cloze"},{"number":9,"points":1,"passage":"Le colis est arrivé pendant mon absence ; le livreur l'a déposé chez le ________ du rez-de-chaussée.","question":"Quel mot complète la phrase ?","options":["médecin","voisin","conducteur","traducteur"],"correct":"B","explanation":"Un voisin du rez-de-chaussée peut recevoir un colis en l'absence du destinataire.","section":"cloze"},{"number":10,"points":1,"passage":"Avant de monter dans le train, pensez à ________ votre billet à la borne prévue.","question":"Quel verbe complète la phrase ?","options":["réparer","annuler","composter","fabriquer"],"correct":"C","explanation":"On peut composter son billet avant de voyager, à la borne de validation.","section":"cloze"},{"number":11,"points":1,"passage":"La réunion débutera à 15 h précises ; merci d'arriver quelques minutes en ________.","question":"Quel mot complète la phrase ?","options":["avance","vacances","absence","urgence"],"correct":"A","explanation":"« Arriver en avance » signifie se présenter avant l'heure fixée.","section":"cloze"},{"number":12,"points":1,"passage":"UN LOGEMENT PLUS ÉCONOME\nPour limiter les dépenses d'énergie, les habitants ont commencé par mieux ________ (1) les fenêtres pendant l'hiver. Ils ont ensuite comparé leurs factures afin d'évaluer les économies réalisées (2).","question":"Quel mot convient à l'espace (1) ?","options":["nettoyer","décorer","ouvrir","isoler"],"correct":"D","explanation":"Isoler les fenêtres réduit les pertes de chaleur en hiver.","section":"paired-cloze","group":"Un logement plus économe"},{"number":13,"points":1,"passage":"UN LOGEMENT PLUS ÉCONOME\nPour limiter les dépenses d'énergie, les habitants ont commencé par mieux isoler les fenêtres pendant l'hiver. Ils ont ensuite comparé leurs factures afin d'évaluer les ________ (2) réalisées.","question":"Quel mot convient à l'espace (2) ?","options":["réunions","réparations","économies","livraisons"],"correct":"C","explanation":"La comparaison des factures permet d'évaluer les économies d'énergie réalisées.","section":"paired-cloze","group":"Un logement plus économe"},{"number":14,"points":1,"passage":"PARTAGER SES COMPÉTENCES\nUne association propose un échange de services : chacun peut offrir quelques heures de son temps pour ________ (1) un voisin dans une démarche ou apprendre quelque chose. Les participants ne reçoivent pas de salaire ; ils comptent sur la ________ (2) entre membres.","question":"Quel mot convient à l'espace (1) ?","options":["accompagner","remplacer","contrôler","convoquer"],"correct":"A","explanation":"Accompagner un voisin dans une démarche correspond à une aide bénévole.","section":"paired-cloze","group":"Partager ses compétences"},{"number":15,"points":1,"passage":"PARTAGER SES COMPÉTENCES\nUne association propose un échange de services : chacun offre du temps pour aider ou apprendre. Les participants ne reçoivent pas de salaire ; ils comptent sur la ________ (2) entre membres.","question":"Quel mot convient à l'espace (2) ?","options":["publicité","concurrence","rapidité","réciprocité"],"correct":"D","explanation":"La réciprocité permet aux participants de s'entraider sans paiement.","section":"paired-cloze","group":"Partager ses compétences"},{"number":16,"points":1,"passage":"DÉCOUVRIR UNE RÉGION\nL'office de tourisme invite les visiteurs à privilégier les déplacements en ________ (1) pour rejoindre les villages reliés par le réseau régional. Cette solution permet aussi de ________ (2) la circulation automobile en été.","question":"Quel mot convient à l'espace (1) ?","options":["train","avion","camion","taxi"],"correct":"A","explanation":"Le train permet de rejoindre les villages desservis par le réseau régional.","section":"paired-cloze","group":"Découvrir une région"},{"number":17,"points":1,"passage":"DÉCOUVRIR UNE RÉGION\nL'office de tourisme conseille le train entre les villages. Cette solution permet aussi de ________ (2) la circulation automobile en été.","question":"Quel mot convient à l'espace (2) ?","options":["multiplier","réduire","interrompre","prolonger"],"correct":"B","explanation":"Le recours au train peut réduire la circulation des voitures.","section":"paired-cloze","group":"Découvrir une région"},{"number":18,"points":1,"passage":"","question":"Quelle offre correspond à un emploi qui se déroule essentiellement en plein air ?","options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"D","explanation":"La quatrième offre concerne l'entretien des sentiers forestiers, une activité extérieure.","section":"offers","media":{"kind":"offers","heading":"Offres d'emploi · Lieu de travail","items":["Centre médical — secrétariat d'accueil en cabinet","Bureau d'études — analyse de plans à distance","Maison d'édition — correction de manuscrits","Parc naturel — entretien de sentiers et balisage"]}},{"number":19,"points":1,"passage":"","question":"Quelle annonce précise que l'employeur fournit un uniforme professionnel ?","options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"B","explanation":"L'offre 2 indique explicitement qu'une tenue de service est fournie.","section":"offers","media":{"kind":"offers","heading":"Offres d'emploi · Tenue de travail","items":["Librairie — tenue personnelle sobre conseillée","Hôtel — réceptionniste, tenue de service fournie","Agence de communication — style vestimentaire libre","Atelier créatif — vêtements adaptés recommandés"]}},{"number":20,"points":1,"passage":"ÉVOLUTION DE LA FRÉQUENTATION DES ACTIVITÉS CULTURELLES\nLes quatre graphiques représentent des séries de cinq années. Choisissez celui qui correspond au commentaire.","question":"Quel graphique montre une baisse initiale, une période de stabilité, puis un retour au niveau de départ ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"A","explanation":"Le graphique 1 commence à 24, descend à 15, reste stable pendant trois années intermédiaires et revient à 24.","section":"charts","media":{"kind":"chart-grid","heading":"Inscriptions aux ateliers culturels","unit":"en milliers de personnes","years":["N−4","N−3","N−2","N−1","N"],"series":[[24,15,15,15,24],[12,18,13,25,20],[9,9,9,9,9],[12,19,28,17,8]]}},{"number":21,"points":1,"passage":"PARTICIPATION AUX ACTIONS LOCALES\nComparez le début et la fin de chaque courbe, en tenant compte du creux intermédiaire.","question":"Quel graphique montre une baisse suivie d'une reprise qui dépasse nettement la valeur initiale ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"C","explanation":"La troisième courbe part de 23, chute à 10, puis monte progressivement jusqu'à 34, au-dessus du niveau initial.","section":"charts","media":{"kind":"chart-grid","heading":"Participants aux projets citoyens","unit":"en milliers de personnes","years":["N−4","N−3","N−2","N−1","N"],"series":[[10,14,18,21,25],[20,20,20,28,28],[23,10,17,26,34],[15,24,16,20,13]]}},{"number":22,"points":1,"passage":"FRÉQUENTATION DES STAGES\nLes variations indiquées sont comparées sur cinq années consécutives.","question":"Quel graphique illustre une baisse progressive puis un retour exact à la valeur de départ ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"B","explanation":"Le graphique 2 montre une diminution de 27 à 17, puis une progression jusqu'à 27, soit exactement la valeur initiale.","section":"charts","media":{"kind":"chart-grid","heading":"Participation aux stages en entreprise","unit":"en milliers de personnes","years":["N−4","N−3","N−2","N−1","N"],"series":[[10,10,10,10,16],[27,22,17,22,27],[11,15,20,25,25],[28,28,12,12,28]]}},{"number":23,"points":1,"passage":"Objet : Changement de dates de votre atelier\nMadame,\nÀ votre demande, nous avons recherché des places pour reporter l'atelier initialement prévu les 6 et 7 avril. Des places sont disponibles les 20 et 21 avril, au même tarif. Merci de confirmer ce nouveau créneau avant le 1er avril. Après cette date, toute modification devra être examinée selon les conditions générales, qui prévoient des frais dans certains cas.\nBien cordialement,\nService des inscriptions.","question":"Quelle proposition est faite à la cliente ?","options":["Une annulation gratuite avec remboursement","Une nouvelle date sans hausse du tarif","Un autre atelier de niveau supérieur","Une réduction valable sur la prochaine session"],"correct":"B","explanation":"Le service propose les 20 et 21 avril au même tarif que le séjour initial.","section":"email","group":"Modification d'inscription"},{"number":24,"points":1,"passage":"Objet : Changement de dates de votre atelier\nMadame,\nÀ votre demande, nous avons recherché des places pour reporter l'atelier initialement prévu les 6 et 7 avril. Des places sont disponibles les 20 et 21 avril, au même tarif. Merci de confirmer ce nouveau créneau avant le 1er avril. Après cette date, toute modification devra être examinée selon les conditions générales, qui prévoient des frais dans certains cas.\nBien cordialement,\nService des inscriptions.","question":"Que se passera-t-il pour une modification demandée après le 1er avril ?","options":["Elle sera acceptée automatiquement","Elle sera obligatoirement refusée","Elle exigera une nouvelle inscription au plein tarif","Elle devra respecter des conditions pouvant inclure des frais"],"correct":"D","explanation":"Après le 1er avril, les conditions générales s'appliquent et des frais sont possibles.","section":"email","group":"Modification d'inscription"},{"number":25,"points":1,"passage":"COMMUNIQUÉ MUNICIPAL — ATELIERS DE PRÉVENTION\nLa ville organise des séances gratuites pour apprendre à réagir aux risques domestiques. Elles s'adressent prioritairement aux familles de jeunes enfants et aux personnes âgées, mais restent ouvertes dans la limite des places disponibles. Les rencontres auront lieu du 3 au 12 juin à la Maison de quartier, sans inscription préalable. Les participants sont invités à apporter un document permettant de confirmer leur adresse.","question":"Comment peut-on participer aux séances ?","options":["En payant une participation au centre municipal","En prenant obligatoirement rendez-vous par téléphone","En demandant une convocation à la mairie","En se présentant gratuitement sans inscription préalable"],"correct":"D","explanation":"Les rencontres sont gratuites et organisées sans inscription préalable.","section":"email","group":"Prévention municipale"},{"number":26,"points":1,"passage":"COMMUNIQUÉ MUNICIPAL — ATELIERS DE PRÉVENTION\nLa ville organise des séances gratuites pour apprendre à réagir aux risques domestiques. Elles s'adressent prioritairement aux familles de jeunes enfants et aux personnes âgées, mais restent ouvertes dans la limite des places disponibles. Les rencontres auront lieu du 3 au 12 juin à la Maison de quartier, sans inscription préalable. Les participants sont invités à apporter un document permettant de confirmer leur adresse.","question":"Quel document est conseillé aux participants ?","options":["Une preuve de domicile","Une attestation d'employeur","Une ordonnance médicale","Un certificat de formation"],"correct":"A","explanation":"Le communiqué demande un document permettant de confirmer l'adresse des participants.","section":"email","group":"Prévention municipale"},{"number":27,"points":1,"passage":"Information importante — Sécurisation de votre espace client\nÀ compter du 15 septembre, la consultation des relevés et la modification de vos coordonnées exigeront une seconde vérification après la saisie du mot de passe. Un code sera envoyé sur le téléphone déjà associé à votre compte. Le tarif de votre abonnement et les modalités de règlement restent inchangés. Une démonstration est disponible sur le site du service.","question":"Quel aspect du service sera modifié ?","options":["Les tarifs des abonnements","La procédure de connexion","Les modalités de facturation","Le contenu des relevés"],"correct":"B","explanation":"Une seconde vérification sera demandée lors de la connexion aux services concernés.","section":"email","group":"Sécurité du compte"},{"number":28,"points":1,"passage":"Information importante — Sécurisation de votre espace client\nÀ compter du 15 septembre, la consultation des relevés et la modification de vos coordonnées exigeront une seconde vérification après la saisie du mot de passe. Un code sera envoyé sur le téléphone déjà associé à votre compte. Le tarif de votre abonnement et les modalités de règlement restent inchangés. Une démonstration est disponible sur le site du service.","question":"Que faudra-t-il faire à partir du 15 septembre ?","options":["Confirmer l'accès grâce à un code reçu sur téléphone","Changer de numéro avant de consulter les relevés","Ouvrir un nouveau compte auprès du service","Régler une cotisation de sécurité supplémentaire"],"correct":"A","explanation":"Le service enverra un code sur le téléphone associé au compte.","section":"email","group":"Sécurité du compte"},{"number":29,"points":1,"passage":"Avis de maintenance\nNotre accueil téléphonique sera suspendu le vendredi 4 novembre de 8 h à 16 h pour la mise à jour du logiciel de réservation. Le formulaire de contact et la messagerie électronique resteront accessibles pendant toute l'intervention. Les demandes reçues seront traitées à partir de 16 h. La ligne téléphonique rouvrira le lendemain selon les horaires habituels.","question":"Par quel moyen sera-t-il possible d'envoyer une demande vendredi à 10 h ?","options":["Par téléphone auprès du standard habituel","Uniquement en se présentant au bureau","Par le formulaire ou par courriel","Par une messagerie réservée aux abonnés"],"correct":"C","explanation":"Le formulaire de contact et le courriel restent disponibles pendant la suspension téléphonique.","section":"email","group":"Maintenance du service"},{"number":30,"points":1,"passage":"Avis de maintenance\nNotre accueil téléphonique sera suspendu le vendredi 4 novembre de 8 h à 16 h pour la mise à jour du logiciel de réservation. Le formulaire de contact et la messagerie électronique resteront accessibles pendant toute l'intervention. Les demandes reçues seront traitées à partir de 16 h. La ligne téléphonique rouvrira le lendemain selon les horaires habituels.","question":"Pourquoi l'accueil téléphonique sera-t-il suspendu ?","options":["En raison d'un changement d'équipe","Pour une intervention sur le logiciel de réservation","À cause d'une fermeture définitive du guichet","Pour organiser une journée de formation"],"correct":"B","explanation":"La suspension est liée à une mise à jour du logiciel de réservation.","section":"email","group":"Maintenance du service"},{"number":31,"points":1,"passage":"Confirmation de formation\nBonjour Madame Martin,\nVotre inscription à la formation « Gestion de projets collaboratifs » a été acceptée. Les cours se tiendront du 5 au 9 décembre, de 9 h à 16 h, dans nos locaux au 18 avenue du Port. Votre entreprise finance la totalité de la formation. Pensez à apporter votre ordinateur et à nous confirmer votre présence avant le 25 novembre. Une attestation vous sera délivrée en fin de session.","question":"Qui prend en charge le coût de la formation ?","options":["L'organisme de formation","La participante elle-même","Une association professionnelle","L'employeur de la participante"],"correct":"D","explanation":"Le message précise que l'entreprise finance la totalité de la formation.","section":"email","group":"Formation professionnelle"},{"number":32,"points":1,"passage":"Confirmation de formation\nBonjour Madame Martin,\nVotre inscription à la formation « Gestion de projets collaboratifs » a été acceptée. Les cours se tiendront du 5 au 9 décembre, de 9 h à 16 h, dans nos locaux au 18 avenue du Port. Votre entreprise finance la totalité de la formation. Pensez à apporter votre ordinateur et à nous confirmer votre présence avant le 25 novembre. Une attestation vous sera délivrée en fin de session.","question":"Quelle démarche est attendue avant le 25 novembre ?","options":["Transmettre un dossier médical","Confirmer sa participation","Réserver un logement à proximité","Régler les frais administratifs"],"correct":"B","explanation":"La participante doit confirmer sa présence avant le 25 novembre.","section":"email","group":"Formation professionnelle"},{"number":33,"points":1,"passage":"TRAVAIL HYBRIDE : TROUVER UN ÉQUILIBRE\nDe plus en plus d'organisations combinent présence au bureau et travail à distance. Cette organisation peut réduire les déplacements et permettre de réserver certaines journées aux tâches exigeant de la concentration. Elle demande toutefois des règles précises pour coordonner les réunions et éviter que les salariés ne soient sollicités à toute heure.\nUne enquête interne révèle que les équipes apprécient la souplesse des horaires, mais que plusieurs employés éprouvent des difficultés à couper leurs notifications le soir. Pour y répondre, l'entreprise propose des plages communes de disponibilité, des réunions préparées à l'avance et un droit explicite à la déconnexion. Les responsables soulignent que la productivité ne se juge pas seulement au temps de présence.","question":"Quel avantage du travail hybride est mentionné ?","options":["La suppression de toutes les réunions","La diminution de certains trajets","L'allongement automatique des congés","La disparition du besoin de coordination"],"correct":"B","explanation":"Le texte indique que l'organisation hybride peut réduire les déplacements.","section":"long","group":"Travail hybride"},{"number":34,"points":1,"passage":"TRAVAIL HYBRIDE : TROUVER UN ÉQUILIBRE\nDe plus en plus d'organisations combinent présence au bureau et travail à distance. Cette organisation peut réduire les déplacements et permettre de réserver certaines journées aux tâches exigeant de la concentration. Elle demande toutefois des règles précises pour coordonner les réunions et éviter que les salariés ne soient sollicités à toute heure.\nUne enquête interne révèle que les équipes apprécient la souplesse des horaires, mais que plusieurs employés éprouvent des difficultés à couper leurs notifications le soir. Pour y répondre, l'entreprise propose des plages communes de disponibilité, des réunions préparées à l'avance et un droit explicite à la déconnexion. Les responsables soulignent que la productivité ne se juge pas seulement au temps de présence.","question":"Quelle difficulté l'entreprise cherche-t-elle à limiter ?","options":["Le manque de matériel de bureau partagé","La suppression des horaires communs","Les sollicitations professionnelles tardives","Le recours excessif aux transports publics"],"correct":"C","explanation":"Le droit à la déconnexion vise les sollicitations et notifications en soirée.","section":"long","group":"Travail hybride"},{"number":35,"points":1,"passage":"LES ATELIERS DE RÉPARATION SOLIDAIRES\nDans plusieurs quartiers, des ateliers associatifs accueillent les habitants qui souhaitent réparer un petit appareil plutôt que le jeter. Des bénévoles apportent des conseils et prêtent des outils, mais la personne reste invitée à participer au diagnostic et au geste technique.\nLes dons permettent d'acheter des pièces et de remplacer le matériel usé. Les organisateurs souhaitent aussi favoriser les échanges entre voisins de générations et d'expériences différentes. Ils rappellent toutefois que certains appareils doivent être confiés à un professionnel lorsqu'une intervention présente un risque de sécurité.","question":"Quel est le rôle principal de ces ateliers ?","options":["Vendre des appareils neufs à prix réduit","Former exclusivement des techniciens salariés","Encourager les réparations accompagnées et les échanges","Remplacer les services professionnels de dépannage"],"correct":"C","explanation":"Les ateliers visent l'apprentissage de gestes de réparation et les échanges entre habitants.","section":"long","group":"Réparation solidaire"},{"number":36,"points":1,"passage":"LES ATELIERS DE RÉPARATION SOLIDAIRES\nDans plusieurs quartiers, des ateliers associatifs accueillent les habitants qui souhaitent réparer un petit appareil plutôt que le jeter. Des bénévoles apportent des conseils et prêtent des outils, mais la personne reste invitée à participer au diagnostic et au geste technique.\nLes dons permettent d'acheter des pièces et de remplacer le matériel usé. Les organisateurs souhaitent aussi favoriser les échanges entre voisins de générations et d'expériences différentes. Ils rappellent toutefois que certains appareils doivent être confiés à un professionnel lorsqu'une intervention présente un risque de sécurité.","question":"Comment financent-ils principalement l'achat des pièces ?","options":["Par des dons","Par une obligation d'abonnement annuel","Par des contrats avec des fabricants","Par la vente systématique des appareils réparés"],"correct":"A","explanation":"Le texte précise que les dons permettent d'acheter des pièces et de remplacer le matériel.","section":"long","group":"Réparation solidaire"},{"number":37,"points":1,"passage":"LE RENOUVEAU DES HALLES DE QUARTIER\nAprès plusieurs années de déclin, les petites halles alimentaires attirent de nouveaux habitants. On y trouve des produits de saison, mais surtout des échanges directs avec des commerçants capables d'expliquer l'origine des produits. Cette proximité séduit les personnes qui cherchent à limiter les emballages et à mieux connaître leur alimentation.\nPour soutenir ces lieux, des municipalités rénovent les bâtiments, simplifient l'installation de jeunes producteurs et améliorent l'information sur les jours d'ouverture. Les commerçants doivent pourtant composer avec la hausse des coûts de transport et la concurrence de la livraison rapide. La fréquentation progresse, sans garantir la rentabilité de chaque stand.","question":"Pourquoi ces halles retrouvent-elles de l'attrait ?","options":["Parce qu'elles proposent surtout des produits importés","Grâce à des tarifs uniformes imposés aux producteurs","Parce que les livraisons y sont gratuites pour tous","Grâce aux contacts directs et à l'origine identifiable des aliments"],"correct":"D","explanation":"Le regain d'intérêt est lié aux échanges avec les producteurs et à la provenance des aliments.","section":"long","group":"Halles de quartier"},{"number":38,"points":1,"passage":"LE RENOUVEAU DES HALLES DE QUARTIER\nAprès plusieurs années de déclin, les petites halles alimentaires attirent de nouveaux habitants. On y trouve des produits de saison, mais surtout des échanges directs avec des commerçants capables d'expliquer l'origine des produits. Cette proximité séduit les personnes qui cherchent à limiter les emballages et à mieux connaître leur alimentation.\nPour soutenir ces lieux, des municipalités rénovent les bâtiments, simplifient l'installation de jeunes producteurs et améliorent l'information sur les jours d'ouverture. Les commerçants doivent pourtant composer avec la hausse des coûts de transport et la concurrence de la livraison rapide. La fréquentation progresse, sans garantir la rentabilité de chaque stand.","question":"Quel soutien municipal est cité ?","options":["La rénovation des locaux et l'aide à l'installation","Le paiement de tous les transports des commerçants","L'interdiction de toute livraison à domicile","L'imposition d'un prix unique à chaque stand"],"correct":"A","explanation":"Le texte mentionne la rénovation des bâtiments et la simplification de l'installation de producteurs.","section":"long","group":"Halles de quartier"},{"number":39,"points":1,"passage":"DES SÉJOURS D'APPRENTISSAGE À LA CAMPAGNE\nCertaines familles choisissent de passer quelques jours dans une exploitation agricole pour découvrir comment sont cultivés les aliments. Les enfants peuvent nourrir les animaux, observer la préparation du pain ou participer à des récoltes adaptées à leur âge. Les hôtes expliquent leurs activités et les contraintes saisonnières.\nCe tourisme apporte un revenu complémentaire aux exploitants. Il ne convient cependant pas à tous : les journées commencent parfois tôt et les activités dépendent de la météo. Les familles qui réservent ce séjour recherchent surtout une expérience concrète plutôt que les équipements d'un grand hôtel.","question":"Quel avantage les enfants retirent-ils de ces séjours ?","options":["Un accès illimité aux équipements numériques","Un entraînement à des compétitions sportives","La découverte pratique du travail agricole","Une formation professionnelle diplômante"],"correct":"C","explanation":"Les enfants observent et participent à des activités agricoles adaptées.","section":"long","group":"Séjours à la campagne"},{"number":40,"points":1,"passage":"DES SÉJOURS D'APPRENTISSAGE À LA CAMPAGNE\nCertaines familles choisissent de passer quelques jours dans une exploitation agricole pour découvrir comment sont cultivés les aliments. Les enfants peuvent nourrir les animaux, observer la préparation du pain ou participer à des récoltes adaptées à leur âge. Les hôtes expliquent leurs activités et les contraintes saisonnières.\nCe tourisme apporte un revenu complémentaire aux exploitants. Il ne convient cependant pas à tous : les journées commencent parfois tôt et les activités dépendent de la météo. Les familles qui réservent ce séjour recherchent surtout une expérience concrète plutôt que les équipements d'un grand hôtel.","question":"Pourquoi certains visiteurs choisissent-ils cette formule malgré ses contraintes ?","options":["Pour bénéficier de services hôteliers de luxe","Pour éviter tout contact avec les animaux","Pour profiter d'activités garanties par tous les temps","Pour vivre une expérience rurale authentique"],"correct":"D","explanation":"Les familles recherchent une expérience concrète de la vie rurale, même avec des horaires matinaux et une météo variable.","section":"long","group":"Séjours à la campagne"}]}$paper$::jsonb);

create function academy_tef_reading.grade(p_paper jsonb,p_answers jsonb) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object(
 'correct',count(*) filter(where p_answers->>(q->>'number')=q->>'correct'),
 'total',count(*),'points',coalesce(sum(case when p_answers->>(q->>'number')=q->>'correct' then (q->>'points')::int else 0 end),0),
 'maxPoints',sum((q->>'points')::int),
 'unanswered',count(*) filter(where not (p_answers ? (q->>'number'))),
 'rows',jsonb_agg(jsonb_build_object('number',q->'number','selected',p_answers->(q->>'number'),'correct',q->>'correct',
 'isCorrect',coalesce(p_answers->>(q->>'number')=q->>'correct',false),'points',case when p_answers->>(q->>'number')=q->>'correct' then (q->>'points')::int else 0 end,
 'maxPoints',q->'points','explanation',q->>'explanation') order by (q->>'number')::int))
 from jsonb_array_elements(p_paper->'questions') q;
$$;
revoke all on function academy_tef_reading.grade(jsonb,jsonb) from public,anon,authenticated,service_role;

-- This narrow authenticated RPC performs entitlement and ownership checks on
-- every action. Private tables and answer keys are never exposed by PostgREST.
create function public.academy_tef_reading_command(p_action text,p_id uuid default null,p_payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();a academy_tef_reading.attempts;paper jsonb;history jsonb;question_no text;choice text;
begin
 perform academy_ai.require_access(u);
 if p_action is null or p_action not in ('catalog','start','read','answer','submit') or p_payload is null or jsonb_typeof(p_payload)<>'object' or octet_length(p_payload::text)>1000 then raise exception 'Invalid reading action';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where not (k=any(case p_action when 'start' then array['testId','version'] when 'answer' then array['number','choice','revision'] when 'submit' then array['revision'] else array[]::text[] end))) then raise exception 'Invalid reading request';end if;
 if p_action='catalog' then
  select coalesce(jsonb_agg(to_jsonb(h) order by h."startedAt" desc),'[]') into history from (
   select id,test_id "testId",version,status,started_at "startedAt",deadline from academy_tef_reading.attempts where user_id=u order by started_at desc limit 50) h;
  return jsonb_build_object('tests',(select jsonb_agg(jsonb_build_object('id',id,'version',version,'title',content->>'title','questions',40,'seconds',3600,'maxPoints',40) order by id) from academy_tef_reading.papers),'history',history,'serverNow',now());
 end if;
 if p_id is null then raise exception 'Invalid reading attempt';end if;
 -- Serialize starts per account, rather than a shared/global lock.
 if p_action='start' then perform 1 from auth.users where id=u for update;end if;
 select * into a from academy_tef_reading.attempts where id=p_id for update;
 if found and a.user_id<>u then raise exception 'Reading attempt not found' using errcode='42501';end if;
 if p_action='start' then
  if p_payload->>'testId' is distinct from 'tef-reading-01' or p_payload->>'version' is distinct from 'tef-reading-2026-11-original-01-v1' then raise exception 'Reading paper changed. Refresh before starting';end if;
  if a.id is not null and (a.test_id<>p_payload->>'testId' or a.version<>p_payload->>'version') then raise exception 'Reading attempt already used';end if;
  if a.id is null then
   -- Finish expired saved work, then resume any unexpired attempt of this paper.
   update academy_tef_reading.attempts t set status='completed',submitted_at=t.deadline,
    result=academy_tef_reading.grade(p.content,t.answers),revision=t.revision+1
    from academy_tef_reading.papers p where t.user_id=u and t.status='active' and now()>=t.deadline and p.id=t.test_id and p.version=t.version;
   select * into a from academy_tef_reading.attempts where user_id=u and status='active' for update;
   if a.id is null then insert into academy_tef_reading.attempts(id,user_id,test_id,version) values(p_id,u,p_payload->>'testId',p_payload->>'version') returning * into a;end if;
  end if;
 end if;
 if a.id is null then raise exception 'Reading attempt not found' using errcode='42501';end if;
 select content into paper from academy_tef_reading.papers where id=a.test_id and version=a.version;
 if a.status='active' and now()>=a.deadline then
  update academy_tef_reading.attempts set status='completed',submitted_at=deadline,result=academy_tef_reading.grade(paper,answers),revision=revision+1 where id=a.id returning * into a;
 end if;
 if a.status='active' and p_action in ('answer','submit') then
  if p_payload->'revision' is distinct from to_jsonb(a.revision) then raise exception 'Reading answers changed in another tab. Reload saved answers';end if;
  if p_action='answer' then
   if jsonb_typeof(p_payload->'number') is distinct from 'number' or p_payload->>'number' !~ '^([1-9]|[12][0-9]|3[0-9]|40)$' or not (p_payload ? 'choice') or (p_payload->'choice'<>'null'::jsonb and (jsonb_typeof(p_payload->'choice')<>'string' or p_payload->>'choice' not in ('A','B','C','D'))) then raise exception 'Invalid reading choice';end if;
   question_no:=p_payload->>'number';choice:=p_payload->>'choice';
   update academy_tef_reading.attempts set answers=case when choice is null then answers-question_no else jsonb_set(answers,array[question_no],to_jsonb(choice)) end,revision=revision+1 where id=a.id returning * into a;
  else
   update academy_tef_reading.attempts set status='completed',submitted_at=now(),result=academy_tef_reading.grade(paper,answers),revision=revision+1 where id=a.id returning * into a;
  end if;
 end if;
 return jsonb_build_object('id',a.id,'testId',a.test_id,'version',a.version,'status',a.status,'answers',a.answers,'revision',a.revision,'startedAt',a.started_at,'deadline',a.deadline,'submittedAt',a.submitted_at,'serverNow',now(),
 'paper',jsonb_build_object('id',a.test_id,'version',a.version,'title',paper->>'title','seconds',paper->'seconds','questions',(select jsonb_agg(q-'correct'-'explanation' order by (q->>'number')::int) from jsonb_array_elements(paper->'questions') q)),
 'result',a.result);
end;$$;
revoke all on function public.academy_tef_reading_command(text,uuid,jsonb) from public,anon,service_role;
grant execute on function public.academy_tef_reading_command(text,uuid,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
